/**
 * Minimal RFC-4180 compliant CSV parser.
 * Handles quoted fields, escaped double-quotes, and CRLF/LF line endings.
 * Returns an array of objects keyed by the lowercased header row values.
 */
export function parseCSV(text: string): Record<string, string>[] {
  const lines = splitLines(text);
  if (lines.length === 0) return [];

  const headers = splitCSVLine(lines[0]).map((h) => h.toLowerCase().trim());

  if (headers.every((h) => h === "")) return [];

  const rows: Record<string, string>[] = [];
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i];
    if (!line.trim()) continue;
    const values = splitCSVLine(line);
    const row: Record<string, string> = {};
    headers.forEach((h, idx) => {
      row[h] = (values[idx] ?? "").trim();
    });
    rows.push(row);
  }
  return rows;
}

function splitLines(text: string): string[] {
  // Split on CRLF or LF, preserve quoted newlines within fields
  const lines: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '"') {
      if (inQuotes && text[i + 1] === '"') {
        current += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
        current += ch;
      }
    } else if ((ch === "\r" || ch === "\n") && !inQuotes) {
      if (ch === "\r" && text[i + 1] === "\n") i++;
      lines.push(current);
      current = "";
    } else {
      current += ch;
    }
  }
  if (current) lines.push(current);
  return lines;
}

function splitCSVLine(line: string): string[] {
  const fields: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      if (inQuotes && line[i + 1] === '"') {
        current += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (ch === "," && !inQuotes) {
      fields.push(current);
      current = "";
    } else {
      current += ch;
    }
  }
  fields.push(current);
  return fields;
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { parseCSV } from "@/lib/csv-parser";
import { VALID_STATUSES, VALID_PRIORITIES } from "@/lib/task-helpers";

// Column name aliases — all lowercased, mapped to canonical column names.
const COLUMN_ALIASES: Record<string, string> = {
  name: "title",
  task: "title",
  "task name": "title",
  "due date": "duedate",
  "due_date": "duedate",
  due: "duedate",
  tag: "tags",
  label: "tags",
  labels: "tags",
  prio: "priority",
  proj: "project",
};

function normalizeHeader(h: string): string {
  const lower = h.toLowerCase().trim();
  return COLUMN_ALIASES[lower] ?? lower.replace(/[\s_-]+/g, "");
}

// Deterministic ID derived from the CSV title so re-importing updates rather than duplicates.
function makeDeterministicId(title: string): string {
  return "csv-" + Buffer.from(title.toLowerCase().trim()).toString("base64url");
}

export async function POST(request: Request) {
  let formData: FormData;
  try {
    formData = await request.formData();
  } catch {
    return NextResponse.json({ error: "Expected multipart/form-data" }, { status: 400 });
  }

  const file = formData.get("file");
  if (!file || !(file instanceof Blob)) {
    return NextResponse.json({ error: "No file uploaded (field name: file)" }, { status: 400 });
  }

  const text = await file.text();

  let rows: Record<string, string>[];
  try {
    rows = parseCSV(text);
  } catch {
    return NextResponse.json({ error: "Failed to parse CSV" }, { status: 400 });
  }

  if (rows.length === 0) {
    return NextResponse.json(
      { error: "CSV has no data rows. Expected a header row followed by at least one data row." },
      { status: 400 },
    );
  }

  // Check that the 'title' column exists (after alias normalization).
  const normalizedKeys = Object.keys(rows[0]).map(normalizeHeader);
  if (!normalizedKeys.includes("title")) {
    return NextResponse.json(
      {
        error:
          'Missing required column "title". ' +
          "Accepted header names: title, name, task. " +
          "Sample header: title,status,priority,project,dueDate,tags",
      },
      { status: 400 },
    );
  }

  let imported = 0;
  let skipped = 0;
  const errors: string[] = [];

  for (let i = 0; i < rows.length; i++) {
    // Normalize raw keys to canonical names.
    const raw = rows[i];
    const row: Record<string, string> = {};
    for (const [k, v] of Object.entries(raw)) {
      row[normalizeHeader(k)] = v;
    }

    const title = row.title?.trim();
    if (!title) {
      skipped++;
      continue;
    }

    const rawStatus = row.status?.toLowerCase().trim() ?? "";
    const status = (VALID_STATUSES as readonly string[]).includes(rawStatus) ? rawStatus : "todo";

    const rawPriority = row.priority?.toLowerCase().trim() ?? "";
    const priority = (VALID_PRIORITIES as readonly string[]).includes(rawPriority)
      ? rawPriority
      : "medium";

    // Tags: semicolon-separated list.
    const tags =
      row.tags?.trim()
        ? row.tags.split(";").map((t) => t.trim()).filter(Boolean)
        : undefined;

    // dueDate: accept YYYY-MM-DD or any Date-parseable string.
    let dueDate: string | null = null;
    if (row.duedate?.trim()) {
      const d = new Date(row.duedate.trim());
      if (!isNaN(d.getTime())) {
        dueDate = row.duedate.trim();
      }
    }

    const id = makeDeterministicId(title);

    try {
      await prisma.task.upsert({
        where: { id },
        create: {
          id,
          title,
          source: "csv",
          status,
          priority,
          project: row.project?.trim() || null,
          dueDate,
          tags: tags ? JSON.stringify(tags) : null,
          sourceUrl: null,
          lastActivity: null,
          assignee: null,
        },
        update: {
          title,
          status,
          priority,
          project: row.project?.trim() || null,
          dueDate,
          tags: tags ? JSON.stringify(tags) : null,
        },
      });
      imported++;
    } catch (err) {
      errors.push(
        `Row ${i + 2}: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }

  return NextResponse.json({ imported, skipped, errors });
}

"use client";

import { useRef, useState } from "react";

interface CsvImportProps {
  onSuccess: () => void;
}

interface ImportResult {
  imported: number;
  skipped: number;
  errors: string[];
}

export function CsvImport({ onSuccess }: CsvImportProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);
  const [result, setResult] = useState<ImportResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  async function handleFile(file: File) {
    setUploading(true);
    setResult(null);
    setErrorMsg(null);

    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("/api/import/csv", { method: "POST", body: formData });
      const data = (await res.json()) as ImportResult & { error?: string };

      if (!res.ok) {
        setErrorMsg(data.error ?? `Error ${res.status}`);
        return;
      }

      setResult(data);
      if (data.imported > 0) onSuccess();
    } catch (err) {
      setErrorMsg(err instanceof Error ? err.message : "Upload failed");
    } finally {
      setUploading(false);
    }
  }

  const label =
    result && !errorMsg
      ? `${result.imported} imported${result.skipped > 0 ? `, ${result.skipped} skipped` : ""}${result.errors.length > 0 ? `, ${result.errors.length} errors` : ""}`
      : null;

  return (
    <div className="flex items-center gap-2">
      <input
        ref={inputRef}
        type="file"
        accept=".csv,text/csv"
        className="hidden"
        onChange={(e) => {
          const file = e.target.files?.[0];
          if (file) {
            void handleFile(file);
            e.target.value = "";
          }
        }}
      />
      <button
        type="button"
        onClick={() => inputRef.current?.click()}
        disabled={uploading}
        className="flex-shrink-0 text-xs px-2.5 py-1 rounded-lg border border-[var(--border)] hover:bg-[var(--bg-hover)] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
      >
        {uploading ? "Importing…" : "Import CSV"}
      </button>
      {label && <span className="text-xs text-emerald-400">{label}</span>}
      {errorMsg && <span className="text-xs text-red-400">{errorMsg}</span>}
    </div>
  );
}

